    Button btnExit;
    ListView lvData;
    ArrayList<String> listEmployee;
    ArrayAdapter<String> adapterEmployee;
    EditText edtid, edtname, edtphone;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        EdgeToEdge.enable(this);
        setContentView(R.layout.activity_employee_management);
        addViews();
        addEvents();
        loadData();
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main), (v, insets) -> {
            Insets systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars());
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom);
            return insets;
        });
    }

    private void addEvents() {
        btnExit.setOnClickListener(view -> processExit());
        lvData.setOnItemClickListener((adapterView, view, position, id) -> displayEmployee(position));
    }

    private void displayEmployee(int i) {
        String data = listEmployee.get(i);
        String[] parts = data.split("-");
        if (parts.length > 0) {
            edtid.setText(parts[0]);
        }
        if (parts.length > 1) {
            edtname.setText(parts[1]);
        }
        if (parts.length > 2) {
            edtphone.setText(parts[2]);
        }
    }

    private void loadData() {
        listEmployee.add("e1-Viet-0987563735");
        listEmployee.add("e2-Hoa-0647485858");
        listEmployee.add("e3-Ngan-0364849959");
        listEmployee.add("e4-Duc-0374844485");
        listEmployee.add("e5-Cam-0374859578");
        adapterEmployee.notifyDataSetChanged();
    }

    private void processExit() {
        Dialog custome = new Dialog(this);
        custome.setContentView(R.layout.custom_dialog);
        ImageView imgSave = custome.findViewById(R.id.imgYes);
        ImageView imgCancel = custome.findViewById(R.id.imgCancel);
        imgSave.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View view) {
                finish();
            }
        });
        imgCancel.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View view) {
                custome.dismiss();
            }
        });
        custome.show();
    }

    private void addViews() {
        btnExit = findViewById(R.id.btnExit);
        lvData = findViewById(R.id.lvData);
        listEmployee = new ArrayList<>();
        adapterEmployee = new ArrayAdapter<>(this, android.R.layout.simple_list_item_1, listEmployee);
        lvData.setAdapter(adapterEmployee);
        edtid = findViewById(R.id.edtid);
        edtname = findViewById(R.id.edtname);
        edtphone = findViewById(R.id.edtphone);
    }

    public void processSave(View view) {
        String id = edtid.getText().toString().trim();
        String name = edtname.getText().toString().trim();
        String phone = edtphone.getText().toString().trim();
        if (id.isEmpty() || name.isEmpty() || phone.isEmpty()) {
            Toast.makeText(this, getString(R.string.str_employee_required), Toast.LENGTH_SHORT).show();
            return;
        }
        String record = id + "-" + name + "-" + phone;
        int index = findEmployeeIndexById(id);
        if (index == -1) {
            listEmployee.add(record);
        } else {
            listEmployee.set(index, record);
        }
        adapterEmployee.notifyDataSetChanged();
    }

    private int findEmployeeIndexById(String id) {
        for (int i = 0; i < listEmployee.size(); i++) {
            String data = listEmployee.get(i);
            String[] parts = data.split("-");
            if (parts.length > 0 && parts[0].equalsIgnoreCase(id)) {
                return i;
            }
        }
        return -1;
    }

    public void processDelete(View view) {
        String id = edtid.getText().toString().trim();
        if (id.isEmpty()) {
            Toast.makeText(this, getString(R.string.str_employee_select_to_delete), Toast.LENGTH_SHORT).show();
            return;
        }
        int index = findEmployeeIndexById(id);
        if (index == -1) {
            Toast.makeText(this, getString(R.string.str_employee_not_found), Toast.LENGTH_SHORT).show();
            return;
        }
        AlertDialog.Builder builder = new AlertDialog.Builder(this);
        builder.setTitle(getString(R.string.str_confirm_delete_title));
        builder.setMessage(getString(R.string.str_confirm_delete_message));
        builder.setPositiveButton(getString(R.string.str_yes), new DialogInterface.OnClickListener() {
            @Override
            public void onClick(DialogInterface dialogInterface, int i) {
                listEmployee.remove(index);
                adapterEmployee.notifyDataSetChanged();
                edtid.setText("");
                edtname.setText("");
                edtphone.setText("");
            }
        });
        builder.setNegativeButton(getString(R.string.str_no), null);
        builder.show();
    }
}
